function equipmentStats(){return inventory.gear.filter(Boolean).reduce((stats,item)=>{for(const [key,value] of Object.entries(item.mods||{}))stats[key]*=value;return stats},{moveSpeed:1,basicDamage:1,magicDamage:1,attackSpeed:1,goldGain:1})}
function conditionalDamageMultiplier(){const charm=inventory.gear.find(item=>item?.id==="gambling-king-charm");return charm?1+charm.trait.minBonus+Math.random()*(charm.trait.maxBonus-charm.trait.minBonus):1}
