function resetCombo(){comboIndex=0;comboExpires=0}
function startAttack(kind){player.attackKind=kind;player.attackDuration=(kind==="down"?.27:kind==="up"?.25:kind==="thrust"?.22:.2)/equipmentStats().attackSpeed;player.attacking=player.attackDuration;player.attackHit=false}
const tutorialSteps=[{action:"move",label:"이동",keys:"A  /  D",text:"앞으로 이동해 훈련을 시작하세요."},{action:"jump",label:"점프",keys:"SPACE",text:"구덩이를 넘어가 보세요. 떨어지면 직전 땅으로 돌아옵니다."},{action:"double",label:"더블 점프",keys:"SPACE × 2",text:"높은 단상은 공중에서 한 번 더 점프해야 오를 수 있습니다."},{action:"collect",label:"필드 아이템",keys:"F",text:"아이템에 닿으면 효과를 확인할 수 있고 F키를 눌러 획득할 수 있습니다."},{action:"equip",label:"자동 장착",keys:"AUTO",text:"훈련의 잔흔은 획득 즉시 자동으로 장착됩니다."},{action:"blue",label:"장막 파괴",keys:"ATTACK + MAGIC",text:"파란 장막에 기본 공격 3회와 마법 1회를 명중시키세요."},{action:"exit",label:"훈련 종료",keys:"FORWARD",text:"연결된 다리를 따라 앞으로 나아가세요."}];
function tutorialAction(action){if(tutorialActive&&tutorialSteps[tutorialStep]?.action===action)tutorialStep++}
function hasTutorialRelicEquipped(){return inventory.equipped.some(item=>item?.id==="tutorial-relic")}
function hasTutorialGearEquipped(){return inventory.gear.some(item=>item?.id==="tutorial-gear")}
function startTutorialMap(){tutorialActive=true;tutorialMode=true;tutorialStep=0;tutorialTransition=0;nearTutorialDrop=null;lastSafePosition={x:170,y:430};player.x=170;player.y=400;player.vx=player.vy=0;player.hp=player.maxHp;greenGate.open=false;blueGate.open=false;blueGate.meleeHits=0;blueGate.magicHits=0;exitBridge.active=false;exitBridge.w=0;tutorialDrops.forEach(drop=>drop.picked=false)}
function finishTutorialMap(){tutorialActive=false;tutorialMode=false;tutorialTransition=2.4;message.innerHTML="훈련장을 지나 왕국의 길로 향합니다.";message.classList.remove("hidden");setTimeout(()=>message.classList.add("hidden"),2400)}
function pickupTutorialDrop(){const drop=nearTutorialDrop;if(!tutorialMode||!drop||drop.picked)return;drop.picked=true;if(drop.type==="relic"){const slot=inventory.equipped.findIndex(item=>!item);if(slot>=0)inventory.equipped[slot]={id:drop.id,name:drop.name,glyph:drop.glyph,color:drop.color,effect:"튜토리얼용 잔흔 · 자동 장착됨"}}else{const slot=inventory.gear.findIndex(item=>!item);if(slot>=0)inventory.gear[slot]={id:drop.id,name:drop.name,glyph:drop.glyph,color:drop.color}}nearTutorialDrop=null;if(drop.type==="relic")tutorialAction("equip")}
function updateTutorialState(){if(!tutorialMode)return;nearTutorialDrop=tutorialDrops.find(drop=>!drop.picked&&Math.abs(player.x+player.w/2-drop.x)<38&&Math.abs(player.y+player.h/2-drop.y)<70)||null;if(tutorialDrops.every(drop=>drop.picked)&&tutorialStep===3)tutorialStep=4;if(!greenGate.open&&hasTutorialRelicEquipped()&&hasTutorialGearEquipped()){greenGate.open=true;if(tutorialStep===4)tutorialStep=5}if(blueGate.open){exitBridge.active=true;exitBridge.w=Math.min(995,exitBridge.w+28);if(tutorialStep===5)tutorialStep=6}if(exitBridge.w>=985&&player.x-world.camera>W-90)finishTutorialMap()}
function damageTutorialPlayer(){player.hp-=10;damageNumbers.push({x:player.x+player.w/2,y:player.y+18,value:"-10",life:.7});if(player.hp<=0)player.hp=player.maxHp;player.x=lastSafePosition.x;player.y=lastSafePosition.y;player.vx=player.vy=0;player.airJumps=0}
addEventListener("keydown",e=>{if(rebindAction){e.preventDefault();bindings[rebindAction]=e.code;rebindAction=null;renderBindings();document.getElementById("settings-note").textContent="";return}if(!gameStarted)return;if(palaceActive){if(e.code==="KeyY")choosePalacePath(true);if(e.code==="KeyN")choosePalacePath(false);e.preventDefault();return}if(e.code===bindings.inventory&&!paused){e.preventDefault();toggleInventory();return}if(e.code==="Escape"&&inventoryOpen){toggleInventory();return}if(e.code==="Escape"){togglePause();return}if(paused)return;if(Object.values(bindings).includes(e.code)||e.code==="KeyS"||e.code==="KeyF")e.preventDefault();if(e.code==="KeyF"&&!e.repeat){pickupTutorialDrop();return}keys.add(e.code);if(e.code===bindings.left){lastMoveDirection=-1;tutorialAction("move")}if(e.code===bindings.right){lastMoveDirection=1;tutorialAction("move")}if(e.code===bindings.jump&&!e.repeat){if(keys.has("KeyS")&&player.standingOnOneWay){player.dropTimer=.24;player.onGround=false;player.standingOnOneWay=false;player.y+=5;resetCombo()}else if(player.onGround){player.vy=-720;player.onGround=false;resetCombo();tutorialAction("jump")}else if(player.airJumps<1){player.vy=-670;player.airJumps++;player.doubleJumpTimer=.26;resetCombo();tutorialAction("double")}}if(e.code===bindings.dash&&!e.repeat&&player.dashCooldown<=0){player.dashTimer=.14;player.dashAttackTimer=.25;player.dashCooldown=.62;player.vx=player.facing*820;resetCombo()}hideIntro()});addEventListener("keyup",e=>{keys.delete(e.code);if(e.code===bindings.left&&lastMoveDirection===-1)lastMoveDirection=keys.has(bindings.right)?1:0;if(e.code===bindings.right&&lastMoveDirection===1)lastMoveDirection=keys.has(bindings.left)?-1:0});canvas.addEventListener("mousedown",e=>{if(e.button||player.attacking>0||inventoryOpen||paused||palaceActive||!gameStarted)return;if(player.dashAttackTimer>0){startAttack("dash");player.dashTimer=0;player.dashAttackTimer=0;resetCombo()}else{if(elapsed>comboExpires)comboIndex=0;const kind=["down","up","thrust"][comboIndex];startAttack(kind);comboIndex=(comboIndex+1)%3;comboExpires=elapsed+.72}hideIntro()});canvas.addEventListener("contextmenu",e=>{e.preventDefault();if(!gameStarted||inventoryOpen||paused||palaceActive||player.magicCooldown>0||player.mp<10)return;player.mp-=10;player.magicCooldown=3;projectiles.push({x:player.x+player.w/2+player.facing*28,y:player.y+35,vx:player.facing*620,life:.62,damage:30*equipmentStats().magicDamage});resetCombo();hideIntro()});
function hideIntro(){if(!introHidden){message.classList.add("hidden");introHidden=true}}
const keyName=code=>({Space:"SPACE",ShiftLeft:"SHIFT",ShiftRight:"SHIFT",Tab:"TAB",KeyA:"A",KeyD:"D"}[code]||code.replace("Key",""));
function renderBindings(){document.querySelectorAll("[data-bind]").forEach(button=>button.textContent=keyName(bindings[button.dataset.bind]))}
