document.body.insertAdjacentHTML("afterbegin",`<section id="palace-audience" class="palace-audience" aria-hidden="true"><div class="palace-scene"><div class="palace-floor"></div><div class="palace-throne"></div><div class="palace-king"></div><div class="palace-hero"></div></div><div class="palace-speech"><div class="palace-speaker">KING</div><p id="palace-speech-text" class="palace-speech-text"></p></div><div id="palace-choice" class="palace-choice" hidden><button id="palace-train"><kbd>Y</kbd> 훈련을 받겠습니다</button><button id="palace-depart"><kbd>N</kbd> 곧바로 출정하겠습니다</button></div></section>`);
const cutsceneEl=document.getElementById("cutscene"),cutsceneArt=document.getElementById("cutscene-art"),cutsceneSubtitle=document.getElementById("cutscene-subtitle");
const palaceEl=document.getElementById("palace-audience"),palaceSpeechText=document.getElementById("palace-speech-text"),palaceChoiceEl=document.getElementById("palace-choice");
const palaceLines=["그대가 이번 소환에 응한 용사로군.","마왕의 군세가 국경을 넘었다. 그자를 쓰러뜨리고 우리 왕국의 평화를 되찾아다오.","출정 전, 훈련이 필요하겠는가?"];
let palaceLineIndex=0,palaceChoiceReady=false,palaceTypeTimer=null,palaceNextTimer=null;
function typeSpeechBubble(element,text,onComplete,rate=42){clearInterval(palaceTypeTimer);let cursor=0;element.textContent="";palaceTypeTimer=setInterval(()=>{element.textContent+=text[cursor++]||"";if(cursor>=text.length){clearInterval(palaceTypeTimer);onComplete?.()}},rate)}
function playPalaceLine(){palaceChoiceEl.hidden=true;typeSpeechBubble(palaceSpeechText,palaceLines[palaceLineIndex],()=>{if(palaceLineIndex===palaceLines.length-1){palaceChoiceReady=true;palaceChoiceEl.hidden=false}else palaceNextTimer=setTimeout(()=>{palaceLineIndex++;playPalaceLine()},1300)})}
function showPalaceAudience(){palaceActive=true;palaceChoiceReady=false;palaceLineIndex=0;palaceEl.classList.add("open");palaceEl.setAttribute("aria-hidden","false");playPalaceLine()}
function choosePalacePath(train){if(!palaceActive||!palaceChoiceReady)return;clearInterval(palaceTypeTimer);clearTimeout(palaceNextTimer);palaceActive=false;keys.clear();lastMoveDirection=0;palaceEl.classList.remove("open");palaceEl.setAttribute("aria-hidden","true");if(train)startTutorialMap();else{tutorialActive=false;tutorialMode=false;player.x=220;player.y=400;player.vx=player.vy=0;message.innerHTML="왕궁을 떠나 마왕성으로 향합니다.";message.classList.remove("hidden");setTimeout(()=>message.classList.add("hidden"),2200)}}
document.getElementById("palace-train").addEventListener("click",()=>choosePalacePath(true));document.getElementById("palace-depart").addEventListener("click",()=>choosePalacePath(false));
function showCutsceneFrame(){const frame=cutsceneFrames[cutsceneIndex];cutsceneArt.src=frame.image;cutsceneSubtitle.textContent="";clearTimeout(cutsceneTimer);clearInterval(typeTimer);let cursor=0;typeTimer=setInterval(()=>{cutsceneSubtitle.textContent+=frame.text[cursor++]||"";if(cursor>=frame.text.length)clearInterval(typeTimer)},52);cutsceneTimer=setTimeout(nextCutsceneFrame,4600)}
function nextCutsceneFrame(){cutsceneIndex++;if(cutsceneIndex>=cutsceneFrames.length)finishCutscene();else showCutsceneFrame()}
function finishCutscene(){clearTimeout(cutsceneTimer);clearInterval(typeTimer);cutsceneEl.classList.remove("open");cutsceneEl.setAttribute("aria-hidden","true");gameStarted=true;introHidden=true;message.classList.add("hidden");document.getElementById("game-root").classList.remove("pre-start");startTutorialMap()}
function startCutscene(){cutsceneIndex=0;cutsceneEl.classList.add("open");cutsceneEl.setAttribute("aria-hidden","false");showCutsceneFrame()}
document.getElementById("skip-cutscene").addEventListener("click",e=>{e.stopPropagation();finishCutscene()});
document.querySelectorAll("[data-bind]").forEach(button=>button.addEventListener("click",()=>{rebindAction=button.dataset.bind;document.getElementById("settings-note").textContent="새로 지정할 키를 누르세요."}));
document.getElementById("open-settings").addEventListener("click",()=>document.getElementById("settings-screen").classList.add("open"));
document.getElementById("close-settings").addEventListener("click",()=>{rebindAction=null;document.getElementById("settings-screen").classList.remove("open")});
document.getElementById("start-game").addEventListener("click",()=>{const title=document.getElementById("title-screen"),panel=document.querySelector(".title-panel"),loading=document.getElementById("loading"),fill=document.getElementById("loading-fill");panel.querySelector(".title-rune").hidden=true;panel.querySelector("h1").hidden=true;panel.querySelector(".title-menu").hidden=true;loading.hidden=false;fill.style.width="0";requestAnimationFrame(()=>fill.style.width="100%");setTimeout(()=>{title.classList.add("hidden");startCutscene()},1350)});
function exitGame(){window.close();document.querySelector(".title-panel").innerHTML="<p>게임이 종료되었습니다.</p>";document.getElementById("title-screen").classList.remove("hidden");document.getElementById("pause-screen").classList.remove("open")}
function togglePause(){paused=!paused;keys.clear();lastMoveDirection=0;document.getElementById("pause-screen").classList.toggle("open",paused);document.getElementById("pause-screen").setAttribute("aria-hidden",String(!paused))}
document.getElementById("exit-game").addEventListener("click",exitGame);document.getElementById("resume-game").addEventListener("click",togglePause);document.getElementById("pause-settings").addEventListener("click",()=>document.getElementById("settings-screen").classList.add("open"));document.getElementById("pause-exit").addEventListener("click",exitGame);
function toggleInventory(){inventoryOpen=!inventoryOpen;keys.clear();lastMoveDirection=0;inventoryEl.classList.toggle("open",inventoryOpen);inventoryEl.setAttribute("aria-hidden",String(!inventoryOpen));if(inventoryOpen)renderInventory()}
function relicDetail(item){selectedItem=item;document.getElementById("detail-icon").textContent=item?item.glyph:"◇";document.getElementById("detail-icon").style.color=item?item.color:"#e8c978";document.getElementById("detail-name").textContent=item?item.name:"아이템을 선택하세요";document.getElementById("detail-text").textContent=item?item.effect||"잔흔 효과가 준비되어 있습니다.":"잔흔은 설정 맵 중앙의 석판에서만 장착하거나 해제할 수 있습니다."}
function equipSelectedRelic(item){const from=inventory.bag.indexOf(item),slot=inventory.equipped.findIndex(x=>!x);if(from<0||slot<0)return;inventory.equipped[slot]=item;inventory.bag[from]=null;selectedItem=null;renderInventory()}
function renderRelicSlot(item,index,kind){const slot=document.createElement("button"),ref={area:kind==="bag"?"bag":"equipped",index};slot.type="button";slot.className=`item-slot ${kind}-slot${item?"":" empty"}${item===selectedItem?" selected":""}`;if(kind==="equip")slot.innerHTML=`<span class="slot-number">${index+1}</span>`;if(item){slot.draggable=relicEditingAllowed;slot.innerHTML+=`<span class="item-token" style="color:${item.color}"><b>${item.glyph}</b></span><small>${item.name}</small>`;slot.addEventListener("dragstart",e=>{if(!relicEditingAllowed)return;e.dataTransfer.setData("text/plain",JSON.stringify(ref));e.dataTransfer.effectAllowed="move"});slot.addEventListener("click",()=>{if(relicEditingAllowed&&kind==="bag"&&selectedItem===item)equipSelectedRelic(item);else if(relicEditingAllowed&&kind==="equip"&&selectedItem===item){const empty=inventory.bag.findIndex(x=>!x);if(empty>=0){inventory.bag[empty]=item;inventory.equipped[index]=null;selectedItem=null;renderInventory()}}else{relicDetail(item);renderInventory()}})}if(relicEditingAllowed){slot.addEventListener("dragover",e=>{e.preventDefault();e.dataTransfer.dropEffect="move"});slot.addEventListener("drop",e=>{e.preventDefault();const from=JSON.parse(e.dataTransfer.getData("text/plain"));if(from.area===ref.area&&from.index===ref.index)return;const source=inventory[from.area][from.index];if(!source)return;const target=inventory[ref.area][ref.index];inventory[ref.area][ref.index]=source;inventory[from.area][from.index]=target;selectedItem=source;renderInventory()})}return slot}
function gearIcon(item){return item.icon?`<span class="gear-art gear-${item.icon}" aria-hidden="true"><i></i><b></b></span>`:`<span class="gear-fallback" aria-hidden="true">${item.glyph||"⚙"}</span>`}
function gearDetail(item){const icon=document.getElementById("gear-detail-icon");icon.innerHTML=item?gearIcon(item):"⚙";icon.style.color=item?item.color:"#e8c978";document.getElementById("gear-detail-name").textContent=item?item.name:"장비를 선택하세요";document.getElementById("gear-detail-text").textContent=item?`${item.grade} 장비 · ${item.effect}`:"장비를 선택하세요. 획득한 장비는 자동으로 장착됩니다."}
function renderGearSlot(item){const slot=document.createElement("button");slot.type="button";slot.className=`item-slot gear-slot${item?"":" empty"}`;if(item){slot.innerHTML=`<span class="gear-token gear-token-art" style="color:${item.color}">${gearIcon(item)}</span><small>${item.name}</small>`;slot.addEventListener("click",()=>gearDetail(item))}return slot}
