function renderInventory(){bagSlots.replaceChildren(...inventory.bag.map((item,index)=>renderRelicSlot(item,index,"bag")));board.replaceChildren(...inventory.equipped.map((item,index)=>renderRelicSlot(item,index,"equip")));gearSlots.replaceChildren(...inventory.gear.map(renderGearSlot));document.getElementById("bag-count").textContent=`${inventory.bag.filter(Boolean).length} / ${inventory.bag.length}`;document.getElementById("gear-count").textContent=`${inventory.gear.filter(Boolean).length} / 10`;relicDetail(selectedItem)}
function setInventoryView(view){const relic=view==="relic";document.getElementById("relic-view").hidden=!relic;document.getElementById("gear-view").hidden=relic;document.querySelectorAll(".inventory-tabs button").forEach(b=>b.classList.toggle("active",b.dataset.view===view))}
document.getElementById("close-inventory").addEventListener("click",toggleInventory);document.querySelectorAll(".inventory-tabs button").forEach(b=>b.addEventListener("click",()=>setInventoryView(b.dataset.view)));
function hurt(enemy,damage){enemy.hp=Math.max(0,enemy.hp-damage);enemy.lastDamagedAt=elapsed;damageNumbers.push({x:enemy.x+enemy.w/2,y:enemy.y+20,value:damage,life:.7});if(enemy.hp===0){enemy.dead=true;enemy.respawnAt=elapsed+3}}
function updateEnemies(){for(const enemy of enemies){if(enemy.dead&&elapsed>=enemy.respawnAt){enemy.dead=false;enemy.hp=enemy.maxHp;enemy.lastDamagedAt=null}}}
function tryAttackHit(){if(player.attackHit)return;const swing=1-player.attacking/player.attackDuration;if(swing<.3||swing>.86)return;const reach=player.attackKind==="thrust"?76:player.attackKind==="dash"?88:62,left=player.facing>0?player.x:player.x-reach,right=player.facing>0?player.x+player.w+reach:player.x+player.w;if(tutorialMode&&!blueGate.open&&blueGate.x<right&&blueGate.x+blueGate.w>left&&player.y+player.h>blueGate.y){blueGate.meleeHits=Math.min(3,blueGate.meleeHits+1);player.attackHit=true;if(blueGate.meleeHits>=3&&blueGate.magicHits>=1)blueGate.open=true;return}for(const enemy of enemies){if(!enemy.dead&&enemy.x<right&&enemy.x+enemy.w>left&&player.y+player.h>enemy.y){player.attackHit=true;hurt(enemy,BASE_DAMAGE*equipmentStats().basicDamage*conditionalDamageMultiplier(),true);break}}}
function updateProjectiles(dt){for(const bolt of projectiles){bolt.x+=bolt.vx*dt;bolt.life-=dt;if(tutorialMode&&!blueGate.open&&bolt.x>blueGate.x&&bolt.x<blueGate.x+blueGate.w&&bolt.y>blueGate.y&&bolt.y<blueGate.y+blueGate.h){blueGate.magicHits=1;bolt.life=0;if(blueGate.meleeHits>=3)blueGate.open=true;continue}for(const enemy of enemies){if(!enemy.dead&&Math.abs(bolt.x-(enemy.x+enemy.w/2))<32&&bolt.y>enemy.y&&bolt.y<enemy.y+enemy.h){hurt(enemy,bolt.damage);bolt.life=0;break}}}for(let i=projectiles.length-1;i>=0;i--)if(projectiles[i].life<=0)projectiles.splice(i,1)}
function update(dt){if(inventoryOpen||paused||!gameStarted)return;elapsed+=dt;tutorialTransition=Math.max(0,tutorialTransition-dt);const d=lastMoveDirection;if(d)player.facing=d;player.dashCooldown=Math.max(0,player.dashCooldown-dt);player.dashAttackTimer=Math.max(0,player.dashAttackTimer-dt);player.magicCooldown=Math.max(0,player.magicCooldown-dt);player.dropTimer=Math.max(0,player.dropTimer-dt);player.doubleJumpTimer=Math.max(0,player.doubleJumpTimer-dt);player.mp=Math.min(player.maxMp,player.mp+dt);if(player.dashTimer>0){player.dashTimer=Math.max(0,player.dashTimer-dt);player.vx=player.facing*820}else player.vx+=(d*360-player.vx)*Math.min(1,dt*14);if(player.attacking>0&&(player.attackKind==="thrust"||player.attackKind==="dash"))player.vx=player.facing*(player.attackKind==="dash"?680:160);player.moving+=Math.abs(player.vx)*dt*.055;player.vy+=1800*dt;player.x+=player.vx*dt;player.y+=player.vy*dt;player.x=Math.max(20,Math.min(world.width-player.w-20,player.x));player.onGround=false;player.standingOnOneWay=false;for(const p of tutorialMode?[...tutorialPlatforms,...(exitBridge.active&&exitBridge.w>0?[exitBridge]:[])]:platforms){if(p.oneWay&&player.dropTimer>0)continue;if(player.x+player.w>p.x&&player.x<p.x+p.w&&player.vy>=0&&player.y+player.h>=p.y&&player.y+player.h-player.vy*dt<=p.y+4){player.y=p.y-player.h;player.vy=0;player.onGround=true;player.standingOnOneWay=p.oneWay;player.airJumps=0}}if(tutorialMode){if(player.x+player.w>tutorialCliff.x&&player.x<tutorialCliff.x+tutorialCliff.w&&player.y+player.h>tutorialCliff.y){if(player.vx>=0)player.x=tutorialCliff.x-player.w;else player.x=tutorialCliff.x+tutorialCliff.w;player.vx=0}for(const gate of [greenGate,blueGate])if(!gate.open&&player.x+player.w>gate.x&&player.x<gate.x+gate.w&&player.y+player.h>gate.y){if(player.vx>=0)player.x=gate.x-player.w;else player.x=gate.x+gate.w;player.vx=0}if(player.onGround)lastSafePosition={x:player.x,y:player.y};if(player.y>H+35)damageTutorialPlayer()}else if(player.y>H+100){player.x=220;player.y=400;player.vx=player.vy=0;player.airJumps=0}if(player.attacking>0)tryAttackHit();player.attacking=Math.max(0,player.attacking-dt);updateEnemies();updateProjectiles(dt);updateTutorialState();for(const number of damageNumbers)number.life-=dt;while(damageNumbers[0]?.life<=0)damageNumbers.shift();const target=Math.max(0,Math.min(world.width-W,player.x-W*.42));world.camera+=(target-world.camera)*Math.min(1,dt*5)}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function background(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,"#192a40");g.addColorStop(.62,"#415870");g.addColorStop(1,"#1c2731");ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.78;ctx.fillStyle="#d9e5d6";ctx.beginPath();ctx.arc(965-world.camera*.08,146,70,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle="#29394d";ctx.beginPath();ctx.moveTo(0,360);for(let x=-100;x<W+200;x+=160){ctx.lineTo(x+70,225+(x/160%3)*35);ctx.lineTo(x+145,360)}ctx.lineTo(W,570);ctx.lineTo(0,570);ctx.fill();ctx.fillStyle="#1c2a38";for(let x=-100;x<W+100;x+=100){ctx.beginPath();ctx.moveTo(x,568);ctx.lineTo(x+46,330+(x/100%2)*40);ctx.lineTo(x+94,568);ctx.fill()}for(const m of motes){const x=m.x-world.camera*.45;if(x<-5||x>W+5)continue;ctx.globalAlpha=m.a*(.65+Math.sin(elapsed+m.x)*.35);ctx.fillStyle="#edf7d9";ctx.beginPath();ctx.arc(x,m.y+Math.sin(elapsed*1.5+m.x)*7,m.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function drawTrainingGroundBack(){const pitStart=350-world.camera,pitEnd=pitStart+140;ctx.fillStyle="#59636b";ctx.fillRect(0,250,W,320);ctx.fillStyle="#424a51";ctx.fillRect(0,226,W,32);for(let x=-20;x<W+35;x+=55){ctx.fillStyle=x%110===-20?"#657077":"#4b555d";ctx.fillRect(x,198,38,29);ctx.fillStyle="#303941";ctx.fillRect(x+10,186,17,12)}ctx.fillStyle="#805052";for(const x of [110,420,760,1080]){ctx.fillRect(x,258,13,145);ctx.beginPath();ctx.moveTo(x+13,266);ctx.lineTo(x+78,282);ctx.lineTo(x+13,320);ctx.fill()}ctx.fillStyle="#d7c58a";for(const x of [250,590,960]){ctx.fillRect(x,350,6,142);ctx.beginPath();ctx.arc(x+3,340,20,0,Math.PI*2);ctx.fill();ctx.strokeStyle="#6d4c35";ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+3,365);ctx.lineTo(x+3,442);ctx.moveTo(x+3,385);ctx.lineTo(x-17,410);ctx.moveTo(x+3,385);ctx.lineTo(x+21,410);ctx.stroke()}ctx.fillStyle="#b08b5e";ctx.fillRect(0,520,Math.max(0,pitStart),48);ctx.fillRect(Math.min(W,pitEnd),520,Math.max(0,W-pitEnd),48);for(let x=0;x<W;x+=48)if(x<pitStart||x>pitEnd)rect(x,532,2,26,"#806345")}
function terrain(){for(const p of tutorialMode?[...tutorialPlatforms,...(exitBridge.active&&exitBridge.w>0?[exitBridge]:[])]:platforms){const x=p.x-world.camera;if(x>W||x+p.w<0)continue;rect(x,p.y,p.w,p.h,tutorialMode?"#3c4347":"#1b2228");rect(x,p.y,p.w,8,tutorialMode?"#a98f67":"#789367");rect(x,p.y+8,p.w,7,tutorialMode?"#725d43":"#40583d");for(let i=18;i<p.w;i+=34)rect(x+i,p.y+16,3,3,tutorialMode?"#585047":"#374149")}}
function drawTutorialFeatures(){if(!tutorialMode)return;if(exitBridge.active){const x=exitBridge.x-world.camera;ctx.fillStyle="#6d5036";ctx.fillRect(x,exitBridge.y,exitBridge.w,9);for(let i=0;i<exitBridge.w;i+=38){rect(x+i,exitBridge.y+4,28,17,"#9a754d");rect(x+i+2,exitBridge.y+6,24,2,"#d3a872")}ctx.strokeStyle="#b99a6b";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,exitBridge.y);ctx.lineTo(x+exitBridge.w,exitBridge.y);ctx.stroke()}for(const drop of tutorialDrops){if(drop.picked)continue;const x=drop.x-world.camera;ctx.save();ctx.translate(x,drop.y+Math.sin(elapsed*2+drop.x)*5);ctx.rotate(Math.PI/4);ctx.fillStyle="#15232c";ctx.fillRect(-16,-16,32,32);ctx.strokeStyle=drop.color;ctx.lineWidth=3;ctx.strokeRect(-16,-16,32,32);ctx.restore();ctx.fillStyle=drop.color;ctx.font="11px monospace";ctx.textAlign="center";ctx.fillText(drop.type==="relic"?"잔흔":"장비",x,drop.y-28);ctx.textAlign="left"}for(const [gate,color,label] of [[greenGate,"#62d693","장착 필요"],[blueGate,"#62a9ea",`${blueGate.meleeHits}/3  ·  마법 ${blueGate.magicHits}/1`]]){if(gate.open)continue;const x=gate.x-world.camera,h=gate.y+gate.h;ctx.save();ctx.globalAlpha=.72;ctx.fillStyle=color;ctx.fillRect(x,0,gate.w,h);ctx.globalAlpha=1;ctx.strokeStyle="#e7f7ed";ctx.lineWidth=2;ctx.strokeRect(x,0,gate.w,h);ctx.fillStyle="#edf8f1";ctx.font="11px monospace";ctx.textAlign="center";ctx.fillText(label,x+gate.w/2,30);ctx.restore();ctx.textAlign="left"}if(nearTutorialDrop){const drop=nearTutorialDrop;ctx.fillStyle="#0c121adf";ctx.fillRect(W/2-210,H-138,420,92);ctx.strokeStyle=drop.color;ctx.strokeRect(W/2-210,H-138,420,92);ctx.fillStyle=drop.color;ctx.font="700 17px serif";ctx.textAlign="center";ctx.fillText(drop.name,W/2,H-108);ctx.fillStyle="#d7e1e4";ctx.font="13px serif";ctx.fillText(drop.effect,W/2,H-83);ctx.fillStyle="#f2ddb0";ctx.font="600 12px monospace";ctx.fillText("[ F ]  획득",W/2,H-60);ctx.textAlign="left"}}
function drawEnemies(){if(tutorialMode)return;for(const enemy of enemies){const x=enemy.x-world.camera;if(x<-100||x>W+100)continue;if(enemy.dead){ctx.fillStyle="#9ba9b6";ctx.font="12px monospace";ctx.textAlign="center";ctx.fillText(`재생성 ${Math.max(0,enemy.respawnAt-elapsed).toFixed(1)}s`,x+enemy.w/2,enemy.y+45);continue}ctx.strokeStyle="#70533a";ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(x+24,enemy.y+48);ctx.lineTo(x+24,enemy.y+100);ctx.moveTo(x+24,enemy.y+66);ctx.lineTo(x+3,enemy.y+82);ctx.moveTo(x+24,enemy.y+66);ctx.lineTo(x+45,enemy.y+82);ctx.stroke();ctx.fillStyle="#d0b06b";ctx.fillRect(x+8,enemy.y+10,32,39);ctx.fillStyle="#352d29";ctx.fillRect(x+15,enemy.y+25,5,5);ctx.fillRect(x+29,enemy.y+25,5,5);ctx.strokeStyle="#322724";ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+24,enemy.y+34,8,0,Math.PI);ctx.stroke();if(enemy.lastDamagedAt!==null&&elapsed-enemy.lastDamagedAt<10){const ratio=enemy.hp/enemy.maxHp;rect(x-7,enemy.y-13,62,8,"#121820");rect(x-6,enemy.y-12,60*ratio,6,"#c15b62");ctx.strokeStyle="#b3c0ca";ctx.lineWidth=1;ctx.strokeRect(x-7,enemy.y-13,62,8)}}}
function drawDamageNumbers(){ctx.textAlign="center";ctx.font="bold 22px monospace";for(const number of damageNumbers){const x=number.x-world.camera,y=number.y-(1-number.life/.7)*32;ctx.globalAlpha=Math.min(1,number.life*3);ctx.fillStyle="#1b1520";ctx.fillText(number.value,x+2,y+2);ctx.fillStyle="#ffe59a";ctx.fillText(number.value,x,y)}ctx.globalAlpha=1}
