let relicAltarActive=false,relicChoices=[];document.head.insertAdjacentHTML("beforeend",`<style>.relic-choice-overlay{position:fixed;z-index:35;inset:0;display:none;place-items:center;background:#050812cc;backdrop-filter:blur(4px)}.relic-choice-overlay.open{display:grid}.relic-choice-card{width:min(860px,calc(100vw - 32px));padding:30px;border:1px solid #829bb0;background:linear-gradient(145deg,#152434,#0a101a);color:#eef4f4;text-align:center}.relic-choice-card h2{margin:0;color:#e3c879}.relic-choice-card p{color:#b7c6cf}.relic-choice-list{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:24px}.relic-choice{min-height:220px;padding:17px;border:1px solid #647b8e;background:#111e2b;color:#e8f0f1;cursor:pointer}.relic-choice:hover{border-color:#e6c978;background:#1c3142}.relic-choice .rune{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 15px;border:2px solid currentColor;transform:rotate(45deg);font-size:1.6rem}.relic-choice .rune b{transform:rotate(-45deg)}.relic-choice button{margin-top:14px;padding:7px 11px;border:1px solid #8295a4;background:#0f1822;color:#e9d28b;cursor:pointer}.relic-choice button:disabled{opacity:.38;cursor:default}</style>`);document.body.insertAdjacentHTML("afterbegin",`<section id="relic-choice-overlay" class="relic-choice-overlay" aria-hidden="true"><div class="relic-choice-card"><h2>잔흔의 석판</h2><p>하나를 선택하면 즉시 장착됩니다. 각 잔흔은 한 번만 다시 뽑을 수 있습니다.</p><div id="relic-choice-list" class="relic-choice-list"></div></div></section>`);const relicChoiceOverlay=document.getElementById("relic-choice-overlay"),relicChoiceList=document.getElementById("relic-choice-list");
function rollRelic(exclude=[]){const pool=RELIC_CATALOG.filter(relic=>unlockedRelicIds.has(relic.id)&&!exclude.includes(relic.id));return pool[Math.floor(Math.random()*pool.length)]}
function renderRelicChoices(){relicChoiceList.replaceChildren(...relicChoices.map((entry,index)=>{const card=document.createElement("article");card.className="relic-choice";card.style.color=entry.relic.color;card.innerHTML=`<div class="rune"><b>${entry.relic.glyph}</b></div><h3>${entry.relic.name}</h3><p>${entry.relic.effect}</p><button aria-label="잔흔 리롤" ${entry.rerolled?"disabled":""}>↻</button>`;card.addEventListener("click",()=>selectRelicChoice(index));card.querySelector("button").addEventListener("click",event=>{event.stopPropagation();if(entry.rerolled)return;entry.relic=rollRelic(relicChoices.filter((_,i)=>i!==index).map(choice=>choice.relic.id));entry.rerolled=true;renderRelicChoices()});return card}))}
function openRelicChoices(){relicChoices=[0,1,2].map(()=>({relic:null,rerolled:false}));relicChoices.forEach((entry,index)=>entry.relic=rollRelic(relicChoices.slice(0,index).map(choice=>choice.relic?.id).filter(Boolean)));relicChoiceOverlay.classList.add("open");relicChoiceOverlay.setAttribute("aria-hidden","false");renderRelicChoices()}
function selectRelicChoice(index){const relic=relicChoices[index].relic,slot=inventory.equipped.findIndex(item=>!item);if(slot>=0)inventory.equipped[slot]={...relic};relicChoiceOverlay.classList.remove("open");relicChoiceOverlay.setAttribute("aria-hidden","true");relicAltarActive=false;beginStageOne()}
function enterRelicAltarMap(){relicAltarActive=true;stageActive=false;world.width=1280;world.camera=0;platforms.splice(0,platforms.length,{x:0,y:568,w:1280,h:160,oneWay:false},{x:510,y:430,w:270,h:28,oneWay:true});enemies.splice(0,enemies.length);player.x=110;player.y=390;player.vx=player.vy=0;message.innerHTML="앞의 잔흔 석판에 다가가 <b>F</b> 키를 누르세요.";message.classList.remove("hidden")}
