finishTutorialMap=function(){tutorialActive=false;tutorialMode=false;inventory.bag=inventory.bag.map(item=>item?.id?.startsWith("tutorial-")?null:item);inventory.equipped=inventory.equipped.map(item=>item?.id?.startsWith("tutorial-")?null:item);inventory.gear=inventory.gear.map(item=>item?.id?.startsWith("tutorial-")?null:item);message.innerHTML="훈련장을 지나 잔흔의 석판으로 향합니다.";message.classList.remove("hidden");setTimeout(()=>{message.classList.add("hidden");enterRelicAltarMap()},1500)};
const renderCombatEnemies=drawEnemies;drawEnemies=function(){if(relicAltarActive){const x=640-world.camera;ctx.save();ctx.translate(x,410);ctx.rotate(Math.PI/4);ctx.fillStyle="#1b2732";ctx.fillRect(-45,-45,90,90);ctx.strokeStyle="#d7c277";ctx.lineWidth=4;ctx.strokeRect(-45,-45,90,90);ctx.restore();ctx.fillStyle="#dbe7e7";ctx.font="15px serif";ctx.textAlign="center";ctx.fillText("잔흔의 석판",x,340);ctx.fillStyle="#e8cf8c";ctx.font="12px monospace";ctx.fillText(Math.abs(player.x-640)<140?"[ F ]  상호작용":"가까이 다가가세요",x,365);ctx.textAlign="left";return}renderCombatEnemies()};
