function hero(){const active=player.attacking>0,swing=active?1-player.attacking/player.attackDuration:0,kind=player.attackKind,visualLunge=active&&["thrust","dash"].includes(kind)?Math.sin(swing*Math.PI)*(kind==="dash"?18:4)*player.facing:0,x=player.x-world.camera+visualLunge,y=player.y,walk=player.onGround?Math.sin(player.moving)*5:0,sheathedAngle=player.facing>0?Math.PI+.88:-.88,sheathStartX=x+(player.facing>0?64:-20),raisedAngle=player.facing>0?-1.15:Math.PI+1.15,lowerAngle=player.facing>0?.85:Math.PI-.85;let angle=lowerAngle;if(kind==="down")angle=raisedAngle+(lowerAngle-raisedAngle)*swing;if(kind==="up")angle=lowerAngle+(raisedAngle-lowerAngle)*swing;if(kind==="thrust"||kind==="dash")angle=player.facing>0?0:Math.PI;const drawDashTrail=()=>{for(let i=3;i>0;i--){ctx.globalAlpha=.07*i;rect(x-player.facing*i*18+9,y+24,28,48,"#b7d9e6")}ctx.globalAlpha=1;ctx.strokeStyle="#d6edf5";ctx.globalAlpha=.45;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-player.facing*68,y+60);ctx.lineTo(x-player.facing*18,y+60);ctx.stroke();ctx.globalAlpha=1};const drawDoubleJump=()=>{const progress=1-player.doubleJumpTimer/.26,cx=x+24,cy=y+75-progress*14;ctx.save();ctx.globalAlpha=.75*(1-progress);ctx.strokeStyle="#9ee9ff";ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(cx,cy,17+progress*18,5+progress*5,0,0,Math.PI*2);ctx.stroke();for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(cx+i*11,cy-3);ctx.lineTo(cx+i*15,cy-17-progress*16);ctx.stroke()}ctx.restore()};const drawSheathedSword=()=>{ctx.save();ctx.translate(sheathStartX,y+73);ctx.rotate(sheathedAngle);rect(0,-2,22,4,"#dce8ed");rect(16,-6,68,12,"#342c3a");rect(76,-9,8,18,"#b89a61");ctx.restore()};const drawAttackSword=()=>{ctx.save();ctx.translate(x+24,y+41);ctx.rotate(angle);rect(0,-4,20,8,"#56616d");rect(18,-2,58,5,"#dce8ed");rect(18,-4,58,2,"#667482");rect(72,-1,8,3,"#fff");ctx.restore()};if(player.dashTimer>0)drawDashTrail();if(player.doubleJumpTimer>0)drawDoubleJump();if(!active)drawSheathedSword();rect(x+10,y+(player.dashTimer>0?5:0)+57,10,20+walk,"#252638");rect(x+27,y+(player.dashTimer>0?5:0)+57,10,20-walk,"#252638");ctx.fillStyle="#705367";ctx.beginPath();ctx.moveTo(x+5,y+30+(player.dashTimer>0?5:0));ctx.lineTo(x+41,y+26+(player.dashTimer>0?5:0));ctx.lineTo(x+45,y+69+(player.dashTimer>0?5:0));ctx.lineTo(x+25,y+61+(player.dashTimer>0?5:0));ctx.lineTo(x+3,y+70+(player.dashTimer>0?5:0));ctx.fill();rect(x+11,y+8+(player.dashTimer>0?5:0),25,27,"#e8c8a0");rect(x+8,y+4+(player.dashTimer>0?5:0),30,12,"#e9e8e0");rect(x+21+player.facing*5,y+20+(player.dashTimer>0?5:0),4,4,"#29313d");if(active)drawAttackSword()}
function hud(){const bar=(y,label,current,max,color)=>{ctx.fillStyle="#0b121abb";ctx.fillRect(23,y,208,16);ctx.fillStyle=color;ctx.fillRect(25,y+2,204*(current/max),12);ctx.fillStyle="#eff5f7";ctx.font="600 11px monospace";ctx.textAlign="left";ctx.fillText(`${label}  ${Math.floor(current)} / ${max}`,30,y+12)};bar(24,"HP",player.hp,player.maxHp,"#b95c67");bar(46,"MP",player.mp,player.maxMp,"#5d80c5");ctx.fillStyle="#e4c577";ctx.font="600 13px monospace";ctx.fillText(`GOLD  ${player.gold}`,25,82);const x=264,y=50,charge=1-player.magicCooldown/3;ctx.save();ctx.beginPath();ctx.moveTo(x,y-25);ctx.lineTo(x+25,y);ctx.lineTo(x,y+25);ctx.lineTo(x-25,y);ctx.closePath();ctx.clip();ctx.fillStyle="#111b27";ctx.fillRect(x-25,y-25,50,50);ctx.fillStyle=player.magicCooldown>0?"#4c89c4":"#7cd7ff";ctx.fillRect(x-25,y+25-50*charge,50,50*charge);ctx.restore();ctx.strokeStyle=player.magicCooldown>0?"#8ba2b7":"#d9f7ff";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y-25);ctx.lineTo(x+25,y);ctx.lineTo(x,y+25);ctx.lineTo(x-25,y);ctx.closePath();ctx.stroke();ctx.fillStyle="#f4fbff";ctx.font="18px serif";ctx.textAlign="center";ctx.fillText("✦",x,y+7);ctx.textAlign="left"}
function drawTutorial(){if(!tutorialActive)return;const step=tutorialSteps[tutorialStep],key=step.action==="move"?`${keyName(bindings.left)}  /  ${keyName(bindings.right)}`:step.action==="jump"?keyName(bindings.jump):step.action==="dash"?keyName(bindings.dash):step.keys,x=W-508,y=24,w=480,h=122,lines=step.text.length>34?[step.text.slice(0,24),step.text.slice(24)]:[step.text];ctx.save();ctx.fillStyle="#0d141bdc";ctx.fillRect(x,y,w,h);ctx.strokeStyle="#c6a96b";ctx.lineWidth=1;ctx.strokeRect(x,y,w,h);ctx.beginPath();ctx.rect(x+1,y+1,w-2,h-2);ctx.clip();ctx.fillStyle="#d9bd7c";ctx.font="600 11px monospace";ctx.textAlign="left";ctx.fillText("ROYAL TRAINING GROUND  ·  기초 훈련",x+18,y+23);ctx.fillStyle="#f4eee0";ctx.font="700 18px serif";ctx.fillText(`${tutorialStep+1}. ${step.label}`,x+18,y+52);ctx.fillStyle="#cbd5d9";ctx.font="13px serif";lines.forEach((line,index)=>ctx.fillText(line,x+18,y+75+index*14));ctx.fillStyle="#17232d";ctx.fillRect(x+342,y+39,118,28);ctx.strokeStyle="#9fb6c3";ctx.strokeRect(x+342,y+39,118,28);ctx.fillStyle="#f1f6f4";ctx.font="600 10px monospace";ctx.textAlign="center";ctx.fillText(key,x+401,y+58);ctx.textAlign="left";ctx.fillStyle="#95a7af";ctx.font="10px monospace";ctx.fillText("공중 SPACE: 더블 점프  ·  발판 위 S + SPACE: 아래로  ·  TAB: 인벤토리",x+18,y+109);for(let i=0;i<tutorialSteps.length;i++){ctx.fillStyle=i<tutorialStep?"#d6bd7e":"#43515b";ctx.beginPath();ctx.arc(x+398+i*11,y+18,3.2,0,Math.PI*2);ctx.fill()}ctx.restore()}
let playerInvulnerableUntil=0,playerFlashUntil=0;
damagePlayer=function(amount){if(elapsed<playerInvulnerableUntil)return;playerInvulnerableUntil=elapsed+.3;playerFlashUntil=elapsed+.085;player.hp=Math.max(0,player.hp-amount);player.vx-=player.facing*95;damageNumbers.push({x:player.x+player.w/2,y:player.y,value:`-${amount}`,life:.7});if(player.hp<=0){player.hp=player.maxHp*.6;player.x=90;player.y=390;player.vx=player.vy=0;message.innerHTML="쓰러졌지만 다시 일어섰습니다.";message.classList.remove("hidden");setTimeout(()=>message.classList.add("hidden"),1300)}};
const baseHurt=hurt;hurt=function(enemy,damage,basicHit=false){baseHurt(enemy,damage,basicHit);if(!enemy.dead)enemy.flashUntil=elapsed+.085};
finishTutorialMap=function(){tutorialActive=false;tutorialMode=false;inventory.bag=inventory.bag.map(item=>item?.id?.startsWith("tutorial-")?null:item);inventory.equipped=inventory.equipped.map(item=>item?.id?.startsWith("tutorial-")?null:item);inventory.gear=inventory.gear.map(item=>item?.id?.startsWith("tutorial-")?null:item);enterRelicAltarMap()};
function drawMysticAltar(){const x=640-world.camera;ctx.fillStyle="#081018";ctx.fillRect(0,0,W,H);for(let i=0;i<45;i++){ctx.globalAlpha=.18+(i%3)*.08;ctx.fillStyle=i%2?"#9473bf":"#5f98b0";ctx.beginPath();ctx.arc((i*113)%W,80+(i*71)%390,1+(i%3),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.fillStyle="#1b2330";ctx.fillRect(0,530,W,38);ctx.fillStyle="#454053";ctx.fillRect(x-150,505,300,25);ctx.fillStyle="#272737";ctx.fillRect(x-105,468,210,40);ctx.save();ctx.translate(x,410);ctx.rotate(Math.PI/4);ctx.fillStyle="#202437";ctx.fillRect(-52,-52,104,104);ctx.strokeStyle="#d2b56d";ctx.lineWidth=4;ctx.strokeRect(-52,-52,104,104);ctx.fillStyle="#7fa9d0";ctx.fillRect(-24,-24,48,48);ctx.restore();ctx.strokeStyle="#8f71b5";ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,410,86,0,Math.PI*2);ctx.stroke();ctx.fillStyle="#e6dcba";ctx.font="18px serif";ctx.textAlign="center";ctx.fillText("잊혀진 잔흔의 석판",x,325);ctx.fillStyle="#aebfd0";ctx.font="12px monospace";ctx.fillText(Math.abs(player.x-640)<140?"[ F ]  석판과 공명하기":"석판에 다가가세요",x,355);ctx.textAlign="left"}
const backgroundBeforeAltar=background;background=function(){if(!relicAltarActive)return backgroundBeforeAltar();drawMysticAltar()};
const enemiesBeforeHitEffects=drawEnemies;drawEnemies=function(){if(relicAltarActive)return;enemiesBeforeHitEffects();if(!stageActive)return;for(const enemy of enemies){if(enemy.dead)continue;const x=enemy.x-world.camera,y=enemy.y;if(enemy.attackTimer>0&&[3,4,5].includes(enemy.type)){ctx.save();ctx.globalAlpha=.24;ctx.fillStyle=enemy.type===5?"#87eaff":"#e49a6b";if(enemy.type===3){ctx.beginPath();ctx.ellipse(x+23,y+75,58,18,0,0,Math.PI*2);ctx.fill()}if(enemy.type===4)ctx.fillRect(x-52,y+28,120,52);if(enemy.type===5){ctx.beginPath();ctx.arc(x+23,y+38,48,0,Math.PI*2);ctx.fill()}ctx.restore()}if(elapsed<(enemy.flashUntil||0)){ctx.save();ctx.globalAlpha=.74;ctx.fillStyle="#ffffff";ctx.fillRect(x+2,y+3,44,72);ctx.restore()}}};
const heroBeforeHitFlash=hero;hero=function(){heroBeforeHitFlash();if(elapsed<playerFlashUntil){const x=player.x-world.camera;ctx.save();ctx.globalAlpha=.72;ctx.fillStyle="#fff";ctx.fillRect(x+4,player.y+4,40,72);ctx.restore()}};
function frame(time){const dt=Math.min(.033,(time-last)/1000||0);last=time;update(dt);background();if(tutorialMode)drawTrainingGroundBack();terrain();drawTutorialFeatures();drawEnemies();drawProjectiles();hero();drawDamageNumbers();hud();drawTutorial();requestAnimationFrame(frame)}requestAnimationFrame(frame);
